'0':y='46*pow(1-clip((t-2.400)/0.55,0,1),3)':enable='between(t,2.400,4.800)':format=auto[b6];[7:v]format=rgba,fade=t=in:st=2.400:d=0.25:alpha=1,fade=t=out:st=4.520:d=0.28:alpha=1[l7];[b6][l7]overlay=x='W*pow(1-clip((t-2.400)/0.75,0,1),3)':y='16*sin(2*PI*(t-2.400)/2.4)':enable='between(t,2.400,4.800)':format=auto[b7];[8:v]format=rgba,fade=t=in:st=2.900:d=0.3:alpha=1,fade=t=out:st=4.520:d=0.28:alpha=1[l8];[b7][l8]overlay=x='-160*pow(1-clip((t-2.900)/0.5,0,1),3)':y='0':enable='between(t,2.400,4.800)':format=auto[b8];[9:v]format=rgba,fade=t=in:st=3.100:d=0.3:alpha=1,fade=t=out:st=4.520:d=0.28:alpha=1[l9];[b8][l9]overlay=x='-160*pow(1-clip((t-3.100)/0.5,0,1),3)':y='0':enable='between(t,2.400,4.800)':format=auto[b9];[10:v]format=rgba,fade=t=in:st=3.300:d=0.3:alpha=1,fade=t=out:st=4.520:d=0.28:alpha=1[l10];[b9][l10]overlay=x='-160*pow(1-clip((t-3.300)/0.5,0,1),3)':y='0':enable='between(t,2.400,4.800)':format=auto[b10];[11:v]format=rgba,fade=t=in:st=4.800:d=0.35:alpha=1,fade=t=out:st=6.920:d=0.28:alpha=1[l11];[b10][l11]overlay=x='0':y='46*pow(1-clip((t-4.800)/0.55,0,1),3)':enable='between(t,4.800,7.200)':format=auto[b11];[12:v]format=rgba,fade=t=in:st=4.800:d=0.25:alpha=1,fade=t=out:st=6.920:d=0.28:alpha=1[l12];[b11][l12]overlay=x='W*pow(1-clip((t-4.800)/0.75,0,1),3)':y='16*sin(2*PI*(t-4.800)/2.4)':enable='between(t,4.800,7.200)':format=auto[b12];[13:v]format=rgba,fade=t=in:st=5.300:d=0.3:alpha=1,fade=t=out:st=6.920:d=0.28:alpha=1[l13];[b12][l13]overlay=x='-160*pow(1-clip((t-5.300)/0.5,0,1),3)':y='0':enable='between(t,4.800,7.200)':format=auto[b13];[14:v]format=rgba,fade=t=in:st=5.500:d=0.3:alpha=1,fade=t=out:st=6.920:d=0.28:alpha=1[l14];[b13][l14]overlay=x='-160*pow(1-clip((t-5.500)/0.5,0,1),3)':y='0':enable='between(t,4.800,7.200)':format=auto[b14];[15:v]format=rgba,fade=t=in:st=5.700:d=0.3:alpha=1,fade=t=out:st=6.920:d=0.28:alpha=1[l15];[b14][l15]overlay=x='-160*pow(1-clip((t-5.700)/0.5,0,1),3)':y='0':enable='between(t,4.800,7.200)':format=auto[b15];[b15]format=yuv420p[v